import itertools
import json

def solve_puzzle():
    houses = [1, 2]  # left to right
    names = ["Arnold", "Eric"]
    sports = ["basketball", "soccer"]
    hair_colors = ["brown", "black"]
    heights = ["very short", "short"]
    smoothies = ["desert", "cherry"]
    flowers = ["daffodils", "carnations"]

    solutions = []

    # Helper for adjacency
    def adjacent(i, j):
        return abs(i - j) == 1

    for name_assign in itertools.permutations(names):
        # name_assign[i] -> name at house i (0-based)
        for sport_assign in itertools.permutations(sports):
            # Clue 1: The person who loves soccer is not in the second house.
            if sport_assign[1] == "soccer":
                continue

            for hair_assign in itertools.permutations(hair_colors):
                for height_assign in itertools.permutations(heights):
                    # Clue 3: The person who is very short is the person who has brown hair.
                    idx_very_short = height_assign.index("very short")
                    if hair_assign[idx_very_short] != "brown":
                        continue

                    # Clue 5: Eric and the person who has brown hair are next to each other.
                    idx_eric = name_assign.index("Eric")
                    idx_brown = hair_assign.index("brown")
                    if not adjacent(idx_eric, idx_brown):
                        continue

                    for smoothie_assign in itertools.permutations(smoothies):
                        # Clue 2: The Desert smoothie lover is directly left of the person who is very short.
                        idx_desert = smoothie_assign.index("desert")
                        if idx_desert + 1 != idx_very_short:
                            continue

                        for flower_assign in itertools.permutations(flowers):
                            # Clue 4: The person who loves a carnations arrangement is the Desert smoothie lover.
                            if flower_assign[idx_desert] != "carnations":
                                continue

                            solutions.append({
                                "Name": list(name_assign),
                                "FavoriteSport": list(sport_assign),
                                "HairColor": list(hair_assign),
                                "Height": list(height_assign),
                                "Smoothie": list(smoothie_assign),
                                "Flower": list(flower_assign),
                            })

    if not solutions:
        raise ValueError("No solution found")

    # Choose the first solution (should be unique for this puzzle)
    sol = solutions[0]

    rows = []
    for i, h in enumerate(houses):
        rows.append([
            str(h),
            sol["Name"][i],
            sol["FavoriteSport"][i],
            sol["HairColor"][i],
            sol["Height"][i],
            sol["Smoothie"][i],
            sol["Flower"][i],
        ])

    output = {
        "solution": {
            "header": ["House", "Name", "FavoriteSport", "HairColor", "Height", "Smoothie", "Flower"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
